CREATE OR REPLACE VIEW `view_urlaubsvorschau_komplett` AS
with krankenquoten as (select `p`.`persnr` AS `persnr`,weekday(`f`.`Datum`) AS `wd`,cast(count(case when `ag`.`krank` = 1 then 1 end) / count(0) as decimal(2,2)) AS `krankenquote`,count(case when `ag`.`anwesenheit` = 'Lfz' then 1 end) / count(0) AS `krankenquote_lfz` from (((`tbl_ueb_fz_buchungen` `f` left join `tbl_ueb_aend_fz_kalender` `fz` on(`fz`.`persnr` = `f`.`PersNr` and `fz`.`datum` = `f`.`Datum`)) join `tbl_datum` `d` on(`f`.`Datum` = `d`.`datum` and `d`.`arbeitstag` = 1 and `d`.`datum` between curdate() - interval 4 month and curdate())) left join `tbl_abwesenheitsgrund` `ag` on(coalesce(`fz`.`wert`,`f`.`Status`) = `ag`.`kuerzel`)) left join `tbl_ueb_personalakte_scd` `p` on(`f`.`PersNr` = `p`.`persnr_alt` and `f`.`Datum` between `p`.`gueltig_von` and `p`.`gueltig_bis`) group by `p`.`persnr`,weekday(`f`.`Datum`)), krankenquote_allgemein as (select `k`.`wd` AS `wd`,cast(avg(`k`.`krankenquote`) as decimal(2,2)) AS `krankenquote`,`p`.`oe` AS `oe` from (`krankenquoten` `k` left join `tbl_ueb_personalakte_scd` `p` on(`p`.`persnr` = `k`.`persnr` and curdate() between `p`.`gueltig_von` and `p`.`gueltig_bis`)) where `p`.`beginn` < curdate() - interval 3 month group by `k`.`wd`,`p`.`oe`), main as (select `u`.`personalnummer` AS `persnr`,`u`.`datum` AS `datum`,`p`.`schichtgruppe` AS `schichtgruppe`,case when `a`.`anwesenheit` <> 'anw' and `d`.`arbeitstag` = 0 then NULL else coalesce(`fz`.`wert`,nullif(`buchungen`.`Status`,''),`u`.`abwesenheitsgrund`) end AS `Status`,cast(case when `p`.`beginn` <= curdate() - interval 120 day then `sr`.`krankenquote` when `p`.`beginn` >= curdate() - interval 60 day then `kqa`.`krankenquote` else (to_days(curdate()) - to_days(`p`.`beginn`) - 60) / 60 * `sr`.`krankenquote` + (120 - (to_days(curdate()) - to_days(`p`.`beginn`))) / 60 * `kqa`.`krankenquote` end as decimal(2,2)) AS `Krankenquote`,cast(`sr`.`krankenquote_lfz` as decimal(2,2)) AS `Krankenquote_Lfz`,`buchungen`.`Kommen` AS `Kommen`,coalesce(`buchungen`.`Schicht`,nullif(`a`.`schicht`,''),`s`.`Schicht`) AS `Schicht`,`a`.`anwesenheit` AS `anwesenheit` from ((((((((`tbl_uebertrag_urlaubsvorschau` `u` left join `tbl_ueb_personalakte_scd` `p` on(`u`.`personalnummer` = `p`.`persnr_alt` and `u`.`datum` between `p`.`gueltig_von` and `p`.`gueltig_bis`)) left join `tbl_ueb_aend_fz_kalender` `fz` on(`fz`.`persnr` = `u`.`personalnummer` and `fz`.`datum` = `u`.`datum`)) left join `krankenquoten` `sr` on(`p`.`persnr` = `sr`.`persnr` and weekday(`u`.`datum`) = `sr`.`wd`)) left join `krankenquote_allgemein` `kqa` on(`p`.`oe` = `kqa`.`oe` and weekday(`u`.`datum`) = `kqa`.`wd`)) left join `tbl_abwesenheitsgrund` `a` on(coalesce(`fz`.`wert`,`u`.`abwesenheitsgrund`) = `a`.`kuerzel`)) left join `tbl_datum` `d` on(`u`.`datum` = `d`.`datum`)) left join `tbl_schichten` `s` on(`d`.`schichtindex` = `s`.`Schichtindex` and `p`.`schichtgruppe` = `s`.`Schichtgruppe`)) left join `view_buchungen_kommen` `buchungen` on(`u`.`personalnummer` = `buchungen`.`PersNr` and `u`.`datum` = `buchungen`.`Datum`)) where `u`.`personalnummer` <> 0)select `main`.`persnr` AS `PersNr`,`main`.`datum` AS `Datum`,`main`.`schichtgruppe` AS `Schichtgruppe`,`main`.`Status` AS `Status`,case when `main`.`anwesenheit` = 'anw' then `main`.`Krankenquote` end AS `Krankenquote`,case when `main`.`anwesenheit` = 'anw' then `main`.`Krankenquote_Lfz` end AS `Krankenquote_Lfz`,`main`.`Kommen` AS `Kommen`,`main`.`Schicht` AS `Schicht` from `main`;
